window.StudioRender=(()=>{
const assetBase=new URL('comic-studio/',document.currentScript.src.replace(/comic-studio\/render\.js.*$/,'')),cache=new Map(),load=src=>{src=new URL(src,assetBase).href;if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=()=>{cache.delete(src);reject(Error('图片载入失败'));};im.src=src;}));return cache.get(src);};
const regions=[{x:28,y:30,w:740,h:612},{x:780,y:32,w:214,h:278},{x:780,y:330,w:214,h:312},{x:28,y:661,w:429,h:417},{x:467,y:661,w:530,h:417},{x:28,y:1097,w:968,h:432}];
function wrap(c,s,w){let lines=[],line='';for(let ch of s){if(ch==='\n'){lines.push(line);line='';continue;}if(c.measureText(line+ch).width>w&&line){if(/[，。！？；：、…）】》]/.test(ch)&&line.length>1){lines.push(line.slice(0,-1));line=line.slice(-1)+ch;}else{lines.push(line);line=ch;}}else line+=ch;}lines.push(line);return lines;}
function refinedText(c,t){const {x,y,w,h}=t,message=t.bubbleStyle==='message',note=t.bubbleStyle==='note',pad=message?22:18,header=message?42:0,bodyY=y+header,bodyH=h-header;c.save();c.fillStyle=message?'#f3f6f4':note?'#fffbef':'#fffefa';c.strokeStyle=message?'#738b88':'#393637';c.lineWidth=message?1.3:1.6;const radius=message?12:note?2:Math.min(32,h*.3);c.beginPath();c.roundRect(x,y,w,h,radius);c.fill();c.stroke();if(t.type==='dialogue'&&t.bubbleStyle==='soft'&&(t.tailY>y+h||t.tailY<y||t.tailX<x||t.tailX>x+w)){const dx=t.tailX-(x+w/2),dy=t.tailY-(y+h/2),k=Math.min((w/2)/Math.max(.001,Math.abs(dx)),(h/2)/Math.max(.001,Math.abs(dy))),bx=x+w/2+dx*k,by=y+h/2+dy*k,len=Math.max(1,Math.hypot(dx,dy)),px=-dy/len*5,py=dx/len*5;c.beginPath();c.moveTo(bx+px,by+py);c.lineTo(t.tailX,t.tailY);c.lineTo(bx-px,by-py);c.closePath();c.fill();c.stroke();c.strokeStyle='#fffefa';c.lineWidth=3;c.beginPath();c.moveTo(bx+px*.85,by+py*.85);c.lineTo(bx-px*.85,by-py*.85);c.stroke();}if(message){c.fillStyle='#3c5954';c.font='bold 17px "Microsoft YaHei",sans-serif';c.textAlign='left';c.textBaseline='middle';c.fillText(t.messageFrom||t.name||'消息',x+pad,y+22);c.strokeStyle='#c6d4ce';c.lineWidth=1;c.beginPath();c.moveTo(x+pad,y+39);c.lineTo(x+w-pad,y+39);c.stroke();}c.font=`${t.size}px "Microsoft YaHei",sans-serif`;const lines=wrap(c,t.text,w-pad*2),lh=t.size*1.4;c.fillStyle=t.type==='thought'?'#615663':'#252d2c';c.textAlign=message||note?'left':'center';c.textBaseline='middle';c.save();c.beginPath();c.rect(x+pad-2,bodyY+5,w-pad*2+4,bodyH-10);c.clip();lines.forEach((line,i)=>c.fillText(line,message||note?x+pad:x+w/2,bodyY+bodyH/2+(i-(lines.length-1)/2)*lh));c.restore();c.restore();return lines.length*lh>bodyH-10;}
function text(c,t){if(['soft','message','note'].includes(t.bubbleStyle))return refinedText(c,t);let {x,y,w,h}=t,cx=x+w/2,cy=y+h/2;c.save();c.fillStyle='white';c.strokeStyle='#272722';c.lineWidth=1.7;if(t.type==='dialogue'&&t.bubbleStyle!=='shout'){let dx=t.tailX-cx,dy=t.tailY-cy,k=1/Math.sqrt(dx*dx/(w*w/4)+dy*dy/(h*h/4));if(Number.isFinite(k)&&k<1){let bx=cx+dx*k*.94,by=cy+dy*k*.94,len=Math.hypot(dx,dy),px=-dy/len*9,py=dx/len*9;c.beginPath();c.moveTo(bx+px,by+py);c.lineTo(t.tailX,t.tailY);c.lineTo(bx-px,by-py);c.closePath();c.fill();c.stroke();}}
if(t.bubbleStyle==='shout'){c.beginPath();for(let i=0;i<32;i++){const angle=i/32*Math.PI*2,r=i%2?0.82:1;c[i?'lineTo':'moveTo'](cx+Math.cos(angle)*w/2*r,cy+Math.sin(angle)*h/2*r);}c.closePath();c.fill();c.stroke();}else if(['dialogue','thought'].includes(t.type)){c.beginPath();c.ellipse(cx,cy,w/2,h/2,0,0,7);c.fill();c.stroke();if(t.type==='thought')for(let i=0;i<2;i++){c.beginPath();c.ellipse(x+w+7+i*9,cy+22+i*7,5-i,4-i,0,0,7);c.fill();c.stroke();}}else if(t.type==='caption'){c.fillStyle='#fffbea';c.fillRect(x,y,w,h);c.strokeRect(x,y,w,h);}
c.font=`${t.type==='title'?'bold ':''}${t.size}px "Microsoft YaHei",sans-serif`;c.textAlign=t.type==='title'?'left':'center';c.textBaseline='middle';c.fillStyle=t.type==='sound'?'white':'#222';let list=wrap(c,t.text,w-22),lh=t.size*1.35;c.save();c.beginPath();c.rect(x+3,y+2,w-6,h-4);c.clip();list.forEach((s,i)=>{let tx=t.type==='title'?x+4:cx,ty=cy+(i-(list.length-1)/2)*lh;if(t.type==='sound'){c.strokeStyle='#222';c.lineWidth=3;c.strokeText(s,tx,ty);}c.fillText(s,tx,ty);});c.restore();c.restore();return list.length*lh>h-2;}
function cover(c,im,b,region=null,crop=null){let r=region||{x:0,y:0,w:im.width,h:im.height},scale=Math.max(b.w/r.w,b.h/r.h)*(crop?.zoom||1),w=r.w*scale,h=r.h*scale;let dx=Math.max(-(w-b.w)/2,Math.min((w-b.w)/2,crop?.x||0)),dy=Math.max(-(h-b.h)/2,Math.min((h-b.h)/2,crop?.y||0));c.save();c.beginPath();c.rect(b.x,b.y,b.w,b.h);c.clip();c.drawImage(im,r.x,r.y,r.w,r.h,b.x-(w-b.w)/2+dx,b.y-(h-b.h)/2+dy,w,h);c.restore();}
async function sources(p,si,f,preview=false){let s=p.scenes[si];if(s.upload){return s.panels.map(()=>({im:null,url:s.upload}));}if(si===0&&p.isSample&&f!=='four'){let im=await load('../comic-page-proof/assets/base.png');if(s.face||preview){let c=document.createElement('canvas');c.width=1024;c.height=1536;c.getContext('2d').drawImage(im,0,0);c.getContext('2d').drawImage(await load('../comic-page-proof/assets/face-candidate.png'),235,670,138,167);im=c;}return regions.map(r=>({im,region:r}));}return s.panels.slice(0,f==='four'?4:12).map((_,i)=>({url:`../comic-lab/assets/scene${si+1}-${i+1}.jpg`}));}
async function draw(canvas,p,si,f=p.format,opt={}){let s=p.scenes[si];if(!s)throw Error('请先安排页面');if(f==='four'&&s.panels.length>4)throw Error('旧页面超过4格，请先回漫画编排拆到新页；原内容和图层均保留，暂不合成四格。');let l=ComicStudio.pageLayout(p,si,f);canvas.width=l.width;canvas.height=l.height;let c=canvas.getContext('2d');c.fillStyle='#fffefa';c.fillRect(0,0,l.width,l.height);
if(f==='pages'&&si===0&&p.isSample&&!s.upload&&s.art&&!s.pageLayout&&!s.panels.some(x=>x.crop)){let im=await load('../comic-page-proof/assets/base.png');c.drawImage(im,0,0,1024,1536);let r=regions[1];cover(c,im,r,r,s.crop);if(s.face||opt.face)c.drawImage(await load('../comic-page-proof/assets/face-candidate.png'),235,670,138,167);}else if(s.upload){cover(c,await load(s.upload),{x:0,y:0,w:l.width,h:l.height},null,s.crop);for(const b of l.boxes){c.strokeStyle='#333c32';c.lineWidth=2;c.strokeRect(b.x,b.y,b.w,b.h);}}else{let src=s.art?await sources(p,si,f,opt.face):[],idx=opt.singleIndex??s.singleIndex??0;if(f==='single')src=[src[Math.max(0,Math.min(src.length-1,idx))]];for(let i=0;i<l.boxes.length;i++){let b=l.boxes[i],panel=s.panels[f==='single'?idx:i],a=src[i];if(panel?.upload)cover(c,await load(panel.upload),b,null,panel.crop);else if(a){let im=a.im||await load(a.url);cover(c,im,b,a.region,panel?.crop||s.crop);}else{c.fillStyle='#f0eee8';c.fillRect(b.x,b.y,b.w,b.h);c.fillStyle='#68746b';c.font='24px sans-serif';c.fillText('第'+(i+1)+'格 · 尚未生成',b.x+20,b.y+45);let lines=wrap(c,panel?.action||'可先编辑文字，或上传图片',b.w-40);lines.slice(0,Math.max(1,Math.floor((b.h-90)/32))).forEach((line,j)=>c.fillText(line,b.x+20,b.y+85+j*32));}c.strokeStyle='#333c32';c.lineWidth=2;c.strokeRect(b.x,b.y,b.w,b.h);}}
let texts=ComicStudio.letters(p,si,f),overflow=[];
for(let t of texts)if(t.text.trim()&&text(c,t))overflow.push(t.name);return {width:l.width,height:l.height,texts,overflow};}
function sketch(p,si){let s=p.scenes[si],l=ComicStudio.pageLayout(p,si);let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${l.width} ${l.height}" role="img" aria-label="当前漫画方案布局草图"><rect width="${l.width}" height="${l.height}" fill="white"/>`;l.boxes.forEach((b,i)=>{svg+=`<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="${i===4||i===2?'#d3dfce':'#ecebe2'}" stroke="#3c5846" stroke-width="4"/><text x="${b.x+b.w/2}" y="${b.y+b.h*.5}" text-anchor="middle" font-size="32" fill="#3c5846">${i+1}</text><ellipse cx="${b.x+b.w*.38}" cy="${b.y+Math.min(80,b.h*.22)}" rx="${Math.min(120,b.w*.28)}" ry="40" fill="white" stroke="#b89a70" stroke-dasharray="8 6" stroke-width="3"/>`;});return svg+'</svg>';}
function draft(canvas,p,si){const s=p.scenes[si],l=ComicStudio.pageLayout(p,si);canvas.width=l.width;canvas.height=l.height;const c=canvas.getContext('2d');c.fillStyle='#fffefa';c.fillRect(0,0,l.width,l.height);c.fillStyle='#42384e';c.font='bold 24px "Microsoft YaHei",sans-serif';c.fillText('分镜排版草稿 · '+s.name,28,36);for(const [i,b]of l.boxes.entries()){const panel=s.panels[p.format==='single'?(s.singleIndex||0):i];c.fillStyle=i%2?'#f2edf6':'#e8e2ef';c.fillRect(b.x,b.y,b.w,b.h);c.strokeStyle='#786389';c.lineWidth=3;c.strokeRect(b.x,b.y,b.w,b.h);c.save();c.beginPath();c.rect(b.x+10,b.y+10,b.w-20,b.h-20);c.clip();const font=b.w<350?23:26,lh=font*1.45;c.font='bold '+font+'px "Microsoft YaHei",sans-serif';c.fillStyle='#513a65';c.fillText('读序 '+(i+1),b.x+20,b.y+38);c.font=font+'px "Microsoft YaHei",sans-serif';const max=Math.max(1,Math.min(4,Math.floor((b.h-130)/lh)));let action=wrap(c,panel?.action||'画面说明待补充',b.w-40);action.slice(0,max).forEach((line,j)=>c.fillText(line+(j===max-1&&action.length>max?'…':''),b.x+20,b.y+80+j*lh));const top=Math.max(b.y+100+Math.min(action.length,max)*lh,b.y+b.h*.58),height=Math.min(b.h-(top-b.y)-18,180);if(height>35){c.fillStyle='#fffefa';c.fillRect(b.x+18,top,b.w-36,height);c.strokeStyle='#b3a4bd';c.setLineDash([7,5]);c.strokeRect(b.x+18,top,b.w-36,height);c.setLineDash([]);c.fillStyle='#72617d';c.font='22px "Microsoft YaHei",sans-serif';const lines=wrap(c,'对白占位：'+(panel?.dialogue||'暂无对白'),b.w-60),limit=Math.max(1,Math.floor((height-18)/30));lines.slice(0,limit).forEach((line,j)=>c.fillText(line+(j===limit-1&&lines.length>limit?'…':''),b.x+30,top+30+j*30));}c.restore();}return {width:l.width,height:l.height,boxes:l.boxes.length,mode:'storyboard-draft'};}
return {load,draw,sketch,draft};})();

